import React, { Component } from 'react'

export class Items extends Component {
  render() {
    return (
        <main>
            {this.props.items.map(el => (
                <div key={el.id} className="item">
                    <h1>{el.title}</h1>
                    <p>{el.desc}</p>
                    <b>{el.price}$</b>
                </div>
            ))}
        </main>
    )
  }
}

export default Items
